import React, { useState, useMemo } from 'react';
import { Typography } from 'antd';
import dayjs from 'dayjs';

// Import custom hooks
import useCalendarNavigation from './hooks/useCalendarNavigation';
import useCalendarDates from './hooks/useCalendarDates';
import useFilteredFlights from './hooks/useFilteredFlights';
import useTooltipManager from './hooks/useTooltipManager';
import useFlightDataProcessor from './hooks/useFlightDataProcessor';

// Import components
import CalendarHeader from './components/CalendarHeader';
import CalendarNavigation from './components/CalendarNavigation';
import CalendarCell from './components/CalendarCell';

// Import utilities
import { getDaysInMonth, getFirstDayOfMonth } from './utils/dateHelpers';
import { generateCalendarCells } from './utils/calendarHelpers';

const { Title } = Typography;

const NormalFlightAvailabilityCalendar = ({ flightData, currentRoute, onDateRangeSelect, selectedRange }) => {
  // Filter states
  const [segmentFilter, setSegmentFilter] = useState({
    mode: 'include',
    segments: []
  });
  const [segmentSearchText, setSegmentSearchText] = useState('');
  const [segmentOrder, setSegmentOrder] = useState([]);
  const [classFilter, setClassFilter] = useState([]);
  const [directFilter, setDirectFilter] = useState(false);
  const [sourceFilter, setSourceFilter] = useState({
    mode: 'include',
    sources: []
  });
  const [sourceSearchText, setSourceSearchText] = useState('');
  const [pointsFilter, setPointsFilter] = useState(null);
  const [airlinesFilter, setAirlinesFilter] = useState({
    mode: 'include',
    airlines: []
  });
  const [airlinesSearchText, setAirlinesSearchText] = useState('');
  const [dateFilter, setDateFilter] = useState([]);
  const [dateSearchText, setDateSearchText] = useState('');
  const [additionalFilters, setAdditionalFilters] = useState([]);
  const [groupFilters, setGroupFilters] = useState({});
  const [segmentFilters, setSegmentFilters] = useState({});
  const [originSearchText, setOriginSearchText] = useState('');
  const [destSearchText, setDestSearchText] = useState('');
  const [groupSourceSearchTexts, setGroupSourceSearchTexts] = useState({});
  const [groupAirlinesSearchTexts, setGroupAirlinesSearchTexts] = useState({});
  const [groupDateSearchTexts, setGroupDateSearchTexts] = useState({});
  const [segmentSourceSearchTexts, setSegmentSourceSearchTexts] = useState({});
  const [segmentAirlinesSearchTexts, setSegmentAirlinesSearchTexts] = useState({});
  const [segmentDateSearchTexts, setSegmentDateSearchTexts] = useState({});

  // Use custom hooks
  const { 
    currentMonth, 
    currentYear, 
    cellPages, 
    goToPrevMonth, 
    goToNextMonth, 
    handlePageChange 
  } = useCalendarNavigation();

  const {
    selectionStart,
    selectionEnd,
    error,
    selectionRef,
    handleDateClick
  } = useCalendarDates(onDateRangeSelect);

  const { activeTooltipRef, showTooltip, hideTooltip } = useTooltipManager();

  // Process the filter data properly 
  const processedGroupFilters = useMemo(() => {
    return Object.entries(groupFilters).reduce((acc, [id, filter]) => {
      acc[id] = {
        ...filter,
        directFilter: !!filter.directFilter, // Ensure boolean
        classFilter: Array.isArray(filter.classFilter) ? filter.classFilter : [],
        sourceFilter: filter.sourceFilter || { mode: 'include', sources: [] },
        airlinesFilter: filter.airlinesFilter || { mode: 'include', airlines: [] },
        pointsFilter: filter.pointsFilter || null,
        dateFilter: filter.dateFilter || []
      };
      return acc;
    }, {});
  }, [groupFilters]);

  const processedSegmentFilters = useMemo(() => {
    return Object.entries(segmentFilters).reduce((acc, [id, filter]) => {
      acc[id] = {
        ...filter,
        directFilter: !!filter.directFilter, // Ensure boolean
        classFilter: Array.isArray(filter.classFilter) ? filter.classFilter : [],
        sourceFilter: filter.sourceFilter || { mode: 'include', sources: [] },
        airlinesFilter: filter.airlinesFilter || { mode: 'include', airlines: [] },
        pointsFilter: filter.pointsFilter || null,
        dateFilter: filter.dateFilter || []
      };
      return acc;
    }, {});
  }, [segmentFilters]);

  const { 
    getEnrichedFlightData, 
    getFilteredFlightData,
    getUniqueSegments, 
    getUniqueSources,
    getUniqueAirlines,
    getPointsRange 
  } = useFlightDataProcessor(flightData);

  // Get filtered flights based on current filters
  const filteredFlights = useFilteredFlights(
    flightData,
    segmentFilter,
    classFilter,
    directFilter,
    sourceFilter,
    airlinesFilter,
    pointsFilter
  );

  // Calendar data
  const daysInMonth = getDaysInMonth(currentYear, currentMonth);
  const firstDayOfMonth = getFirstDayOfMonth(currentYear, currentMonth);

  // Generate calendar cells
  const calendarCells = useMemo(() => {
    return generateCalendarCells(currentYear, currentMonth, daysInMonth, firstDayOfMonth);
  }, [currentYear, currentMonth, daysInMonth, firstDayOfMonth]);

  return (
    <div className="flight-availability-calendar">
      {/* Header with filters would go here */}

      <CalendarNavigation 
        currentMonth={currentMonth}
        currentYear={currentYear}
        goToPrevMonth={goToPrevMonth}
        goToNextMonth={goToNextMonth}
      />

      <div className="calendar-grid">
        <CalendarHeader />

        <div className="calendar-body">
          {calendarCells.map((cell, index) => {
            if (cell.type === 'blank') {
              return <div key={`blank-${index}`} className="calendar-cell empty" />;
            }

            return (
              <CalendarCell
                key={`day-${cell.day}`}
                year={currentYear}
                month={currentMonth}
                day={cell.day}
                flightData={flightData}
                currentRoute={currentRoute}
                selectionRef={selectionRef}
                handleDateClick={handleDateClick}
                cellPages={cellPages}
                handlePageChange={handlePageChange}
                // Filters
                classFilter={classFilter}
                directFilter={directFilter}
                sourceFilter={sourceFilter}
                airlinesFilter={airlinesFilter}
                pointsFilter={pointsFilter}
                dateFilter={dateFilter}
                groupFilters={processedGroupFilters}
                segmentFilters={processedSegmentFilters}
                // Helpers
                getEnrichedFlightData={getEnrichedFlightData}
                getFilteredFlightData={getFilteredFlightData}
                activeTooltipRef={activeTooltipRef}
              />
            );
          })}
        </div>
      </div>

      {error && (
        <div className="error-message">{error}</div>
      )}
    </div>
  );
};

export default NormalFlightAvailabilityCalendar;
